import React, { useEffect, useState } from "react";
import axios from "axios";
import PageHeader from "./PageHeader";
import SectionCard from "./SectionCard";
import DashboardCard from "./DashboardCard";
import AlertBox from "./AlertBox";
import { FaClipboardList, FaUpload, FaBook } from "react-icons/fa";
import "./dashboard.css";

function AssignmentsStudent() {
  const studentId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [files, setFiles] = useState({});
  const [selectedCourse, setSelectedCourse] = useState("");
  const [alert, setAlert] = useState(null);

  useEffect(() => {
    loadCourses();
  }, []);

  const loadCourses = async () => {
    const coursesRes = await axios.get("http://127.0.0.1:8000/courses");
    const enrollRes = await axios.get(`http://127.0.0.1:8000/enrollments/${studentId}`);

    const enrolledIds = enrollRes.data.map(e => e.course_id);

    setCourses(
      (coursesRes.data.courses || []).filter(c => enrolledIds.includes(c.id))
    );
  };

  const loadAssignments = async (courseId) => {
    const res = await axios.get(`http://127.0.0.1:8000/assignments/${courseId}`);
    setAssignments(res.data.assignments || []);
  };

  const handleSubmit = async (assignmentId) => {
    const file = files[assignmentId];

    if (!file) {
      setAlert({ message: "Select file first", type: "error" });
      return;
    }

    const formData = new FormData();
    formData.append("assignment_id", assignmentId);
    formData.append("student_id", studentId);
    formData.append("file", file);

    const res = await axios.post(
      "http://127.0.0.1:8000/submit-assignment",
      formData,
      {}
    );

    setAlert({ message: res.data.message, type: "success" });
  };

  return (
    <div>
      {alert && <AlertBox {...alert} onClose={() => setAlert(null)} />}

      <PageHeader
        title="Assignments"
        subtitle="Upload your answers as PDF or images."
      />

      <div className="grid-3" style={{ marginBottom: 20 }}>
        <DashboardCard icon={<FaBook />} label="Courses" value={courses.length} />
        <DashboardCard icon={<FaClipboardList />} label="Assignments" value={assignments.length} />
        <DashboardCard icon={<FaUpload />} label="Submission" value="Active" />
      </div>

      <SectionCard title="Select Course">
        <select
          className="select"
          value={selectedCourse}
          onChange={(e) => {
            setSelectedCourse(e.target.value);
            loadAssignments(e.target.value);
          }}
        >
          <option value="">Select Course</option>
          {courses.map(c => (
            <option key={c.id} value={c.id}>{c.title}</option>
          ))}
        </select>
      </SectionCard>

      <SectionCard title="Assignments">
        {assignments.map(a => (
          <div className="list-card" key={a.id}>
            <h4>{a.title}</h4>
            <div className="meta">{a.description}</div>
            <div className="meta">Due: {a.due_date}</div>

            <input
              type="file"
              onChange={(e) =>
                setFiles({ ...files, [a.id]: e.target.files[0] })
              }
            />

            <button className="btn btn-primary" onClick={() => handleSubmit(a.id)}>
              Upload Answer
            </button>
          </div>
        ))}
      </SectionCard>
    </div>
  );
}

export default AssignmentsStudent;
